 84	export const sessionHandlers: Record<string, Handler<any, any>> = {
 85	  [Methods.GetConsiliumSessions]: async (_, ctx) => {
 86	    if (!ctx.workDir) return [];
 87	    const sessions = await listSessions(ctx.workDir);
 88	    for (const s of sessions) {
 89	      const meta = ctx.getSessionMetadata(s.id);
 90	      s.brief = meta?.title || s.brief;
 91	      (s as any).mode = meta?.mode || 'legacy';
 92	    }
 93	    return sessions;
 94	  },
 95	
 96	  [Methods.GetAllConsiliumSessions]: async (_, ctx) => {
 97	    if (!ctx.workspaceRoot) return [];
 98	
 99	    // The SDK hashes workDir case-sensitively. On Windows the same folder can
100	    // appear under c:\ and C:\ hashes. Query every registered variant.
101	    const registered = getRegisteredWorkDirs(ctx.workspaceRoot);
102	    const allSessions: SessionInfo[] = [];
103	    const seen = new Set<string>();
104	
105	    for (const dir of registered) {
106	      try {
107	        const sess = await listSessions(dir);
108	        for (const s of sess) {
109	          if (!seen.has(s.id)) {
110	            seen.add(s.id);
111	            const meta = ctx.getSessionMetadata(s.id);
112	            s.brief = meta?.title || s.brief;
113	            (s as any).mode = meta?.mode || 'legacy';
114	            allSessions.push(s);
115	          }
116	        }
117	      } catch {
118	        // ignore missing directories
119	      }
120	    }
121	
122	    // Also surface Think sessions (not scanned by SDK)
123	    for (const s of await listThinkSessions()) {
124	      if (!seen.has(s.id)) {
125	        seen.add(s.id);
126	        const meta = ctx.getSessionMetadata(s.id);
127	        // Keep the first-message brief unless the user set a custom title.
128	        s.brief = meta?.title || s.brief;
129	        (s as any).mode = meta?.mode || 'think';
130	        allSessions.push(s);
131	      }
132	    }
133	
134	    return allSessions.sort((a, b) => b.updatedAt - a.updatedAt);
135	  },
