137	  [Methods.GetRegisteredWorkDirs]: async (_, ctx) => {
138	    return ctx.workspaceRoot ? getRegisteredWorkDirs(ctx.workspaceRoot) : [];
139	  },
140	
141	  [Methods.SetWorkDir]: async (params: { workDir: string | null }, ctx) => {
142	    if (!ctx.workspaceRoot) {
143	      return { ok: false };
144	    }
145	    const target = params.workDir;
146	    if (target && target !== ctx.workspaceRoot && !target.startsWith(ctx.workspaceRoot + path.sep)) {
147	      return { ok: false };
148	    }
149	    ctx.setCustomWorkDir(target);
150	    return { ok: true, workDir: target || ctx.workspaceRoot };
151	  },
152	
153	  [Methods.BrowseWorkDir]: async (_, ctx) => {
154	    if (!ctx.workspaceRoot) {
155	      return { ok: false, workDir: null };
156	    }
157	    const workspaceUri = vscode.Uri.file(ctx.workspaceRoot);
158	    let subdirs: string[] = [];
159	    try {
160	      const entries = await vscode.workspace.fs.readDirectory(workspaceUri);
161	      subdirs = entries
162	        .filter(([, type]) => type === vscode.FileType.Directory)
163	        .map(([name]) => name)
164	        .filter((name) => !name.startsWith("."))
165	        .sort();
166	    } catch {
167	      // Ignore errors
168	    }
169	
170	    const items: vscode.QuickPickItem[] = [
171	      { label: "$(folder) Browse...", description: "Open folder picker", alwaysShow: true },
172	      { label: "", kind: vscode.QuickPickItemKind.Separator },
173	      ...subdirs.map((name) => ({
174	        label: `$(folder) ${name}`,
175	        description: path.join(ctx.workspaceRoot!, name),
176	      })),
177	    ];
178	
179	    const picked = await vscode.window.showQuickPick(items, {
180	      placeHolder: "Select a subdirectory or browse...",
181	      title: "Working Directory",
182	    });
183	
184	    if (!picked) {
185	      return { ok: false, workDir: null };
186	    }
187	
188	    let selected: string;
189	    if (picked.label === "$(folder) Browse...") {
190	      const result = await vscode.window.showOpenDialog({
191	        canSelectFiles: false,
192	        canSelectFolders: true,
193	        canSelectMany: false,
194	        defaultUri: workspaceUri,
195	        openLabel: "Select Working Directory",
196	      });
197	      if (!result || result.length === 0) {
198	        return { ok: false, workDir: null };
199	      }
200	      selected = result[0].fsPath;
201	    } else {
202	      selected = picked.description!;
203	    }
204	
205	    if (selected !== ctx.workspaceRoot && !selected.startsWith(ctx.workspaceRoot + path.sep)) {
206	      vscode.window.showWarningMessage("Selected directory must be within the workspace.");
207	      return { ok: false, workDir: null };
208	    }
209	
210	    ctx.setCustomWorkDir(selected === ctx.workspaceRoot ? null : selected);
211	    return { ok: true, workDir: selected };
212	  },
