  1	/**
  2	 * Extension-side session title persistence.
  3	 *
  4	 * Regular sessions: titles are written to the CLI's per-session state.json.
  5	 * Think sessions: titles are written to a sidecar JSON file next to the JSONL history.
  6	 *
  7	 * This file lives in the extension source so it is built with the extension;
  8	 * it does not require rebuilding the agent_sdk package.
  9	 */
 10	
 11	import * as fs from "node:fs";
 12	import * as path from "node:path";
 13	import * as os from "node:os";
 14	import * as crypto from "node:crypto";
 15	
 16	export type TitleSource = "user" | "llm" | "fallback";
 17	
 18	export interface SessionTitle {
 19	  title: string;
 20	  source: TitleSource;
 21	  generatedAt?: number;
 22	}
 23	
 24	interface CliSessionState {
 25	  version?: number;
 26	  custom_title?: string | null;
 27	  title_generated?: boolean;
 28	  [key: string]: unknown;
 29	}
 30	
 31	interface ThinkSessionMetadata {
 32	  title?: string;
 33	  titleSource?: TitleSource;
 34	  titleGeneratedAt?: number;
 35	  mode?: "think" | "do" | "legacy";
 36	}
 37	
 38	function hashPath(workDir: string): string {
 39	  return crypto.createHash("md5").update(workDir, "utf-8").digest("hex");
 40	}
 41	
 42	function getShareDir(): string {
 43	  return process.env.KIMI_SHARE_DIR || path.join(os.homedir(), ".consilium");
 44	}
 45	
 46	function sessionDir(workDir: string, sessionId: string): string {
 47	  return path.join(getShareDir(), "sessions", hashPath(workDir), sessionId);
 48	}
 49	
 50	function readJsonFile<T>(filePath: string): T | null {
 51	  try {
 52	    return JSON.parse(fs.readFileSync(filePath, "utf-8")) as T;
 53	  } catch {
 54	    return null;
 55	  }
 56	}
 57	
 58	function atomicWriteJson(filePath: string, data: unknown): void {
 59	  const dir = path.dirname(filePath);
 60	  if (!fs.existsSync(dir)) {
 61	    fs.mkdirSync(dir, { recursive: true });
 62	  }
 63	  const tempPath = `${filePath}.tmp`;
 64	  fs.writeFileSync(tempPath, JSON.stringify(data, null, 2), "utf-8");
 65	  try {
 66	    fs.renameSync(tempPath, filePath);
 67	  } catch {
 68	    fs.writeFileSync(filePath, JSON.stringify(data, null, 2), "utf-8");
 69	  }
 70	}
 71	
 72	function readLegacyMetadata(sessionDirPath: string): { title?: string } | null {
 73	  try {
 74	    return JSON.parse(fs.readFileSync(path.join(sessionDirPath, "metadata.json"), "utf-8"));
 75	  } catch {
 76	    return null;
 77	  }
 78	}
 79	
 80	/** Read a regular session title from CLI state.json, falling back to legacy metadata.json. */
 81	export function readSessionTitle(workDir: string, sessionId: string): SessionTitle | null {
 82	  const dir = sessionDir(workDir, sessionId);
 83	  const state = readJsonFile<CliSessionState>(path.join(dir, "state.json"));
 84	  if (state?.custom_title) {
 85	    return {
 86	      title: state.custom_title,
 87	      source: state.title_generated ? "llm" : "user",
 88	    };
 89	  }
 90	
 91	  const metadata = readLegacyMetadata(dir);
 92	  if (metadata?.title) {
 93	    return { title: metadata.title, source: "fallback" };
 94	  }
 95	
 96	  return null;
 97	}
 98	
 99	/** Write a regular session title to CLI state.json, preserving other fields. */
100	export function writeSessionTitle(
101	  workDir: string,
102	  sessionId: string,
103	  title: string,
104	  source: TitleSource,
105	  generatedAt?: number,
106	): void {
107	  const dir = sessionDir(workDir, sessionId);
108	  const statePath = path.join(dir, "state.json");
109	  const state = readJsonFile<CliSessionState>(statePath) ?? { version: 1 };
110	
111	  state.custom_title = title;
112	  state.title_generated = source === "llm";
113	
114	  // Store extension-specific source/timestamp as extra fields; CLI ignores unknown fields.
115	  (state as Record<string, unknown>)["title_source"] = source;
116	  if (generatedAt !== undefined) {
117	    (state as Record<string, unknown>)["title_generated_at"] = generatedAt;
118	  }
119	
120	  atomicWriteJson(statePath, state);
121	}
122	
123	function getThinkDir(): string {
124	  // Think sessions are always stored under the user's home directory, not KIMI_SHARE_DIR.
125	  return path.join(os.homedir(), ".consilium", "think_sessions");
126	}
127	
128	function thinkMetadataPath(sessionId: string): string {
129	  return path.join(getThinkDir(), `${sessionId}.json`);
130	}
131	
132	/** Read a Think session title from its sidecar metadata file. */
133	export function readThinkSessionTitle(sessionId: string): SessionTitle | null {
134	  const meta = readJsonFile<ThinkSessionMetadata>(thinkMetadataPath(sessionId));
135	  if (meta?.title) {
136	    return {
137	      title: meta.title,
138	      source: meta.titleSource ?? "fallback",
139	      generatedAt: meta.titleGeneratedAt,
140	    };
141	  }
142	  return null;
143	}
144	
145	/** Write a Think session title to its sidecar metadata file. */
146	export function writeThinkSessionTitle(
147	  sessionId: string,
148	  title: string,
149	  source: TitleSource,
150	  generatedAt?: number,
151	): void {
152	  const filePath = thinkMetadataPath(sessionId);
153	  const meta = readJsonFile<ThinkSessionMetadata>(filePath) ?? {};
154	
155	  meta.title = title;
156	  meta.titleSource = source;
157	  if (generatedAt !== undefined) {
158	    meta.titleGeneratedAt = generatedAt;
159	  }
160	
161	  atomicWriteJson(filePath, meta);
162	}

