253	  [Methods.SetWorkDir]: async (params: { workDir: string | null }, ctx) => {
254	    if (!ctx.workspaceRoot) {
255	      return { ok: false };
256	    }
257	    const target = params.workDir;
258	    if (target && target !== ctx.workspaceRoot && !target.startsWith(ctx.workspaceRoot + path.sep)) {
259	      return { ok: false };
260	    }
261	    ctx.setCustomWorkDir(target);
262	    return { ok: true, workDir: target || ctx.workspaceRoot };
263	  },
264	
265	  [Methods.BrowseWorkDir]: async (_, ctx) => {
266	    if (!ctx.workspaceRoot) {
267	      return { ok: false, workDir: null };
268	    }
269	    const workspaceUri = vscode.Uri.file(ctx.workspaceRoot);
270	    let subdirs: string[] = [];
271	    try {
272	      const entries = await vscode.workspace.fs.readDirectory(workspaceUri);
273	      subdirs = entries
274	        .filter(([, type]) => type === vscode.FileType.Directory)
275	        .map(([name]) => name)
276	        .filter((name) => !name.startsWith("."))
277	        .sort();
278	    } catch {
279	      // Ignore errors
280	    }
281	
282	    const items: vscode.QuickPickItem[] = [
283	      { label: "$(folder) Browse...", description: "Open folder picker", alwaysShow: true },
284	      { label: "", kind: vscode.QuickPickItemKind.Separator },
285	      ...subdirs.map((name) => ({
286	        label: `$(folder) ${name}`,
287	        description: path.join(ctx.workspaceRoot!, name),
288	      })),
289	    ];
290	
291	    const picked = await vscode.window.showQuickPick(items, {
292	      placeHolder: "Select a subdirectory or browse...",
293	      title: "Working Directory",
294	    });
295	
296	    if (!picked) {
297	      return { ok: false, workDir: null };
298	    }
299	
300	    let selected: string;
301	    if (picked.label === "$(folder) Browse...") {
302	      const result = await vscode.window.showOpenDialog({
303	        canSelectFiles: false,
304	        canSelectFolders: true,
305	        canSelectMany: false,
306	        defaultUri: workspaceUri,
307	        openLabel: "Select Working Directory",
308	      });
309	      if (!result || result.length === 0) {
310	        return { ok: false, workDir: null };
311	      }
312	      selected = result[0].fsPath;
313	    } else {
314	      selected = picked.description!;
315	    }
316	
317	    if (selected !== ctx.workspaceRoot && !selected.startsWith(ctx.workspaceRoot + path.sep)) {
318	      vscode.window.showWarningMessage("Selected directory must be within the workspace.");
319	      return { ok: false, workDir: null };
320	    }
321	
322	    ctx.setCustomWorkDir(selected === ctx.workspaceRoot ? null : selected);
323	    return { ok: true, workDir: selected };
324	  },
325	
326	  [Methods.LoadConsiliumSessionHistory]: async (params: LoadHistoryParams, ctx): Promise<StreamEvent[]> => {
327	    if (!UUID_REGEX.test(params.consiliumSessionId)) {
328	      return [];
329	    }
330	
331	    const thinkFile = path.join(getThinkDir(), `${params.consiliumSessionId}.jsonl`);
332	    const isThinkFile = fs.existsSync(thinkFile);
333	
334	    // Think sessions can be loaded without a workspace; Do sessions require one.
335	    if (!isThinkFile && !ctx.workDir) {
336	      return [];
337	    }
338	
339	    const fileKey = ctx.getFileManagerKey();
340	    ctx.fileManager.setSessionId(fileKey, params.consiliumSessionId);
341	    if (ctx.workDir) {
342	      BaselineManager.initSession(ctx.workDir, params.consiliumSessionId);
343	    }
344	
345	    // ---- Think session path (base history) ----
346	    const thinkEvents: StreamEvent[] = [];
347	    if (isThinkFile) {
348	      const lines = (await fs.promises.readFile(thinkFile, "utf-8"))
349	        .split("\n")
350	        .filter((l) => l.trim());
351	      for (const line of lines) {
352	        try {
353	          const entry = JSON.parse(line);
354	          if (entry.role === "user" || entry.role === "assistant") {
355	            thinkEvents.push({
356	              type: "Message",
357	              payload: { role: entry.role, content: entry.content },
358	              _sessionId: params.consiliumSessionId,
359	              mode: 'think',
360	            } as any);
361	          }
362	        } catch {
363	          // ignore malformed lines
364	        }
365	      }
366	    }
367	
368	    const meta = ctx.getSessionMetadata(params.consiliumSessionId);
369	    // If a think file exists and the stored mode is not explicitly 'do', treat it as a Think session.
370	    // This protects against lost globalState after extension reinstall.
371	    const mode = meta?.mode || (isThinkFile ? 'think' : 'legacy');
372	    const resolvedMode: 'think' | 'do' = mode === 'do' ? 'do' : 'think';
373	
374	    if (resolvedMode === 'think') {
375	      // Force terminal event so Think tab doesn't get stuck
376	      thinkEvents.push({
377	        type: "history_restored",
378	        result: { status: "restored" },
379	        _sessionId: params.consiliumSessionId,
380	        mode: 'think',
381	      } as any);
382	      return thinkEvents;
383	    }
384	
385	    // ---- Regular Do session path ----
386	    // Prefer the workDir supplied by the caller; fall back to registered
387	    // variants to handle Windows case-sensitivity differences.
388	    let doEvents: StreamEvent[] = [];
389	    const candidateWorkDirs = new Set<string>();
390	    if (params.workDir) candidateWorkDirs.add(params.workDir);
391	    if (ctx.workDir) candidateWorkDirs.add(ctx.workDir);
392	    if (ctx.workspaceRoot) {
393	      for (const dir of getRegisteredWorkDirs(ctx.workspaceRoot)) {
394	        candidateWorkDirs.add(dir);
395	      }
396	    }
397	    if (candidateWorkDirs.size === 0) {
398	      return [];
399	    }
400	    for (const dir of candidateWorkDirs) {
401	      try {
402	        const events = await parseSessionEvents(dir, params.consiliumSessionId);
403	        if (events.length > 0) {
404	          doEvents = events;
405	          break;
406	        }
407	      } catch {
408	        // try next candidate
409	      }
410	    }
411	
412	    const events = [
413	      ...thinkEvents,
414	      ...doEvents.map((e) => ({ ...e, _sessionId: params.consiliumSessionId, mode: 'do' as const }) as any),
415	    ];
416	
417	    // If the previous CLI process was killed (window reload), wire.jsonl ends
418	    // mid-stream. The webview would stay stuck in isProcessing=true.
419	    // Append a history_restored event to unlock the UI.
420	    if (!ctx.getTurn()) {
421	      const last = events[events.length - 1] as any;
422	      const isTerminal =
423	        last &&
424	        (last.type === "stream_complete" ||
425	          last.type === "stream_aborted" ||
426	          last.type === "history_restored" ||
427	          last.type === "error" ||
428	          last.type === "turn_complete" ||
429	          last.type === "done");
430	      if (!isTerminal) {
431	        events.push({
432	          type: "history_restored",
433	          result: { status: "restored" },
434	          _sessionId: params.consiliumSessionId,
435	          mode: 'do',
436	        } as any);
437	      }
438	    }
439	
440	    return events;
441	  },
442	
443	  [Methods.DeleteConsiliumSession]: async (params: DeleteSessionParams, ctx): Promise<{ ok: boolean }> => {
444	    if (!ctx.workDir || !UUID_REGEX.test(params.sessionId)) {
445	      return { ok: false };
446	    }
447	    return { ok: await deleteSession(ctx.workDir, params.sessionId) };
448	  },
449	
450	  [Methods.ForkConsiliumSession]: async (params: ForkSessionParams, ctx): Promise<ForkSessionResult | null> => {
451	    if (!ctx.workDir || !UUID_REGEX.test(params.sessionId) || params.turnIndex < 0) {
452	      return null;
453	    }
454	    try {
455	      return await forkSession({
456	        workDir: ctx.workDir,
457	        sourceSessionId: params.sessionId,
458	        turnIndex: params.turnIndex,
459	      });
460	    } catch (err) {
461	      handlerLog.error("Fork session failed", { error: String(err) });
462	      return null;
463	    }
464	  },
465	
466	  [Methods.WriteSessionMetadata]: async (params: WriteSessionMetadataParams, ctx) => {
467	    const { sessionId, title, source } = params;
468	    const meta = ctx.getSessionMetadata(sessionId) ?? {};
469	    ctx.setSessionMetadata(sessionId, {
470	      ...meta,
471	      title,
472	      titleSource: source,
473	      titleGeneratedAt: source === "llm" ? Date.now() : meta.titleGeneratedAt,
474	    });
475	    ctx.broadcast(
476	      Events.SessionTitleUpdated,
477	      { sessionId, title, source },
478	      ctx.webviewId,
479	    );
480	    return { ok: true };
481	  },
482	
483	  [Methods.RestoreTabState]: async (_, ctx) => {
484	    return ctx.getRestoredTabState();
485	  },
486	};
