 1	/**
 2	 * Derive a session display title from the first user message.
 3	 *
 4	 * This keeps the history list readable without relying on the CLI to name
 5	 * sessions. Custom titles set in session metadata take precedence over derived
 6	 * titles.
 7	 */
 8	
 9	export const DEFAULT_FALLBACK_TITLE = "Untitled Session";
10	export const DEFAULT_MAX_TITLE_LENGTH = 60;
11	
12	/**
13	 * Truncate plain text to a reasonable title length, adding an ellipsis only
14	 * when the text is longer than the limit.
15	 */
16	export function deriveTitleFromText(
17	  text: string,
18	  maxLength: number = DEFAULT_MAX_TITLE_LENGTH,
19	): string {
20	  const normalized = text.trim().replace(/\s+/g, " ");
21	  if (normalized.length <= maxLength) {
22	    return normalized;
23	  }
24	  return normalized.slice(0, maxLength - 1).trimEnd() + "…";
25	}
26	
27	/**
28	 * Extract a single display string from session message content. Handles plain
29	 * strings and arrays of content parts (text/image/video).
30	 */
31	export function extractTextFromContent(content: unknown): string {
32	  if (typeof content === "string") {
33	    return content;
34	  }
35	  if (Array.isArray(content)) {
36	    return content
37	      .map((part: any) => {
38	        if (typeof part === "string") return part;
39	        if (part?.type === "text" && typeof part.text === "string") {
40	          return part.text;
41	        }
42	        return "";
43	      })
44	      .join(" ")
45	      .trim();
46	  }
47	  return "";
48	}
49	
50	/**
51	 * Find the first user message in a list of session entries and return its text.
52	 * Each entry is expected to have `role` and `content` fields, matching both
53	 * Think session JSONL entries and SDK message shapes.
54	 */
55	export function extractFirstUserMessageText(
56	  entries: Array<{ role?: string; content?: unknown }>,
57	): string | null {
58	  for (const entry of entries) {
59	    if (entry.role === "user") {
60	      const text = extractTextFromContent(entry.content);
61	      if (text) {
62	        return text;
63	      }
64	    }
65	  }
66	  return null;
67	}
68	
69	/**
70	 * Derive a title from raw JSONL session file lines. Returns `null` if no usable
71	 * first user message is found.
72	 */
73	export function deriveTitleFromSessionLines(lines: string[]): string | null {
74	  const entries: Array<{ role?: string; content?: unknown }> = [];
75	  for (const line of lines) {
76	    if (!line.trim()) continue;
77	    try {
78	      entries.push(JSON.parse(line));
79	    } catch {
80	      // ignore malformed lines
81	    }
82	  }
83	  const first = extractFirstUserMessageText(entries);
84	  return first ? deriveTitleFromText(first) : null;
85	}

  1	import { useMemo, useState } from "react";
  2	import { useRequest } from "ahooks";
