 29	interface SessionItemProps {
 30	  session: SessionInfo;
 31	  isSelected: boolean;
 32	  onSelect: () => void;
 33	  onDelete: () => void;
 34	  onRename: (sessionId: string, newTitle: string) => Promise<void>;
 35	  dirLabel: string | null; // null = current dir, string = relative path
 36	}
