 38	function ModeBadge({ mode }: { mode?: string }) {
 39	  if (!mode) mode = 'legacy';
 40	  return (
 41	    <span className={cn(
 42	      "inline-flex items-center rounded-sm px-1 py-0.5 text-[9px] font-medium uppercase tracking-wider shrink-0",
 43	      mode === 'think' && "bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-300",
 44	      mode === 'do' && "bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300",
 45	      mode === 'legacy' && "bg-muted text-muted-foreground"
 46	    )}>
 47	      {mode === 'legacy' ? 'Think' : mode}
 48	    </span>
 49	  );
 50	}
