 52	function SessionItem({ session, isSelected, onSelect, onDelete, onRename, dirLabel }: SessionItemProps) {
 53	  const [isHovered, setIsHovered] = useState(false);
 54	  const [isEditing, setIsEditing] = useState(false);
 55	  const [editValue, setEditValue] = useState(session.brief);
 56	
 57	  const commitEdit = async () => {
 58	    setIsEditing(false);
 59	    const trimmed = editValue.trim();
 60	    if (trimmed && trimmed !== session.brief) {
 61	      await onRename(session.id, trimmed);
 62	    } else if (!trimmed) {
 63	      setEditValue(session.brief);
 64	    }
 65	  };
 66	
 67	  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
 68	    if (e.key === "Enter") {
 69	      e.preventDefault();
 70	      commitEdit();
 71	    } else if (e.key === "Escape") {
 72	      e.preventDefault();
 73	      setIsEditing(false);
 74	      setEditValue(session.brief);
 75	    }
 76	  };
 77	
 78	  return (
 79	    <div
 80	      className={cn("group relative px-2 py-1 rounded-md cursor-pointer transition-colors", isSelected ? "bg-accent" : "hover:bg-accent/50")}
 81	      onMouseEnter={() => setIsHovered(true)}
 82	      onMouseLeave={() => setIsHovered(false)}
 83	      onClick={onSelect}
 84	    >
 85	      {isEditing ? (
 86	        <Input
 87	          autoFocus
 88	          value={editValue}
 89	          onChange={(e) => setEditValue(e.target.value)}
 90	          onKeyDown={handleKeyDown}
 91	          onBlur={commitEdit}
 92	          onClick={(e) => e.stopPropagation()}
 93	          className="h-6 text-xs py-0 px-1"
 94	        />
 95	      ) : (
 96	        <p className="text-xs leading-relaxed line-clamp-3 text-foreground">{cleanSystemTags(session.brief) || "Untitled"}</p>
 97	      )}
 98	      <div className="flex items-center justify-between mt-1">
 99	        <div className="flex items-center gap-1.5 min-w-0 flex-1">
100	          {isSelected && <IconCheck className="size-3 text-blue-500 shrink-0" />}
101	          <ModeBadge mode={(session as any).mode} />
102	          <span className="text-[10px] text-muted-foreground shrink-0">{formatRelativeDate(session.updatedAt)}</span>
103	          {dirLabel && <span className="text-[10px] text-muted-foreground/70 truncate" title={session.workDir}>· {dirLabel}</span>}
104	        </div>
105	        <div className={cn("flex items-center gap-0.5 transition-opacity", isHovered ? "opacity-100" : "opacity-0")}>
106	          <button
107	            className="p-1 -m-1 rounded hover:bg-muted transition-colors"
108	            onClick={(e) => {
109	              e.stopPropagation();
110	              setIsEditing(true);
111	              setEditValue(session.brief);
112	            }}
113	            title="Rename"
114	          >
115	            <IconPencil className="size-3.5 text-muted-foreground" />
116	          </button>
117	          <DropdownMenu>
118	            <DropdownMenuTrigger asChild>
119	              <button className="p-1 -m-1 rounded hover:bg-muted transition-colors" onClick={(e) => e.stopPropagation()}>
120	                <IconDots className="size-3.5 text-muted-foreground" />
121	              </button>
122	            </DropdownMenuTrigger>
123	            <DropdownMenuContent align="end" className="w-32">
124	              <DropdownMenuItem
125	                className="text-xs text-destructive focus:text-destructive cursor-pointer"
126	                onClick={(e) => {
127	                  e.stopPropagation();
128	                  onDelete();
129	                }}
130	              >
131	                <IconTrash className="size-3.5 mr-2" />
132	                Delete
133	              </DropdownMenuItem>
134	            </DropdownMenuContent>
135	          </DropdownMenu>
136	        </div>
137	      </div>
138	    </div>
139	  );
140	}
