142	export function SessionList({ onClose }: SessionListProps) {
143	  const { loadSession, sessionId, startNewConversation, isStreaming, renameSession } = useChatStore();
144	  const { workspaceRoot, currentWorkDir, setCurrentWorkDir } = useSettingsStore();
145	  const [searchQuery, setSearchQuery] = useState("");
146	  const [deleteTarget, setDeleteTarget] = useState<SessionInfo | null>(null);
147	  const [isDeleting, setIsDeleting] = useState(false);
148	  const [pendingSession, setPendingSession] = useState<SessionInfo | null>(null);
149	
150	  const { data: consiliumSessions = [], loading, mutate } = useRequest(() => bridge.getAllConsiliumSessions());
151	
152	  const getWorkDirLabel = (sessionWorkDir: string): string | null => {
153	    const activeWorkDir = currentWorkDir || workspaceRoot;
154	    if (sessionWorkDir === activeWorkDir) return null;
155	    if (!workspaceRoot) return sessionWorkDir;
156	    // Show (root) for workspace root, relative path for subdirs
157	    if (sessionWorkDir === workspaceRoot) {
158	      return "/";
159	    }
160	    if (sessionWorkDir.startsWith(workspaceRoot)) {
161	      return "." + sessionWorkDir.slice(workspaceRoot.length);
162	    }
163	    return sessionWorkDir;
164	  };
165	
166	  const filteredSessions = useMemo(() => {
167	    if (!searchQuery.trim()) return consiliumSessions;
168	    const q = searchQuery.toLowerCase();
169	    return consiliumSessions.filter((s) => s.brief.toLowerCase().includes(q));
170	  }, [consiliumSessions, searchQuery]);
171	
172	  const handleSelect = async (session: SessionInfo) => {
173	    console.log("[SessionList] Loading session:", session.id);
174	    
175	    // If streaming, show confirmation dialog
176	    if (isStreaming) {
177	      setPendingSession(session);
178	      return;
179	    }
180	    
181	    await doLoadSession(session);
182	  };
183	
184	  const handleRename = async (sessionId: string, newTitle: string) => {
185	    await renameSession(sessionId, newTitle);
186	    mutate();
187	  };
188	
189	  const doLoadSession = async (session: SessionInfo) => {
190	    try {
191	      // Switch workDir if session is from a different directory.
192	      // Think sessions are global and do not have a project workDir.
193	      const isThinkSession = session.workDir === "[Think]";
194	      if (!isThinkSession) {
195	        const activeWorkDir = currentWorkDir || workspaceRoot;
196	        if (session.workDir !== activeWorkDir) {
197	          const newWorkDir = session.workDir === workspaceRoot ? null : session.workDir;
198	          const result = await bridge.setWorkDir(newWorkDir);
199	          if (result.ok) {
200	            setCurrentWorkDir(newWorkDir);
201	          }
202	        }
203	      }
204	
205	      // Sync the toggle state with the session mode
206	      useSettingsStore.getState().setThinkingEnabled(session.isThinking);
207	
208	      // Switch to the tab that owns this session before loading its history,
209	      // otherwise events without _sessionId will render in the active tab.
210	      const mode = (session as any).mode === 'do' ? 'do' : 'think';
211	      useChatStore.getState().setActiveTab(mode);
212	
213	      const events = await bridge.loadSessionHistory(session.id, isThinkSession ? undefined : session.workDir);
214	      await loadSession(session.id, events, { title: session.brief });
215	      onClose();
216	    } catch (error) {
217	      console.error("[SessionList] Failed to load session:", error);
218	    }
219	  };
220	
221	  const handleConfirmSwitch = async () => {
222	    if (!pendingSession) return;
223	    await doLoadSession(pendingSession);
224	    setPendingSession(null);
225	  };
226	
227	  const handleDelete = async () => {
228	    if (!deleteTarget) return;
229	
230	    setIsDeleting(true);
231	    try {
232	      await bridge.deleteSession(deleteTarget.id);
233	
234	      if (sessionId === deleteTarget.id) {
235	        await startNewConversation();
236	      }
237	
238	      mutate((prev) => prev?.filter((s) => s.id !== deleteTarget.id) || []);
239	    } catch (error) {
240	      console.error("[SessionList] Failed to delete session:", error);
241	    } finally {
242	      setIsDeleting(false);
243	      setDeleteTarget(null);
244	    }
245	  };
246	
247	  return (
248	    <>
249	      <div className="flex flex-col max-h-[70vh]">
